package com.jfvag.aibox;
import android.content.*;import java.net.*;import java.io.*;import java.nio.charset.StandardCharsets;
public final class TouchpadServer {
 private final Context context; private ServerSocket server;private volatile boolean running;
 public TouchpadServer(Context c){context=c.getApplicationContext();}
 public static String code(Context c){android.content.SharedPreferences p=c.getSharedPreferences("JF_BRIDGE",Context.MODE_PRIVATE);String s=p.getString("touchpad_pair","");if(!s.matches("[0-9]{6}")){s=String.format(java.util.Locale.US,"%06d",new java.security.SecureRandom().nextInt(1000000));p.edit().putString("touchpad_pair",s).apply();}return s;}
 public synchronized void start(){if(running)return;running=true;new Thread(()->{try{server=new ServerSocket(18777);server.setSoTimeout(1000);while(running){try{Socket s=server.accept();s.setSoTimeout(2500);new Thread(()->handle(s),"JF Touchpad Client").start();}catch(SocketTimeoutException ignored){}}}catch(Exception e){android.util.Log.e("JF-Touchpad","server error",e);}finally{running=false;try{if(server!=null)server.close();}catch(Exception ignored){}}},"JF Touchpad Server").start();}
 public synchronized void stop(){running=false;try{if(server!=null)server.close();}catch(Exception ignored){}}
 private void handle(Socket s){try(s){BufferedReader in=new BufferedReader(new InputStreamReader(s.getInputStream(),StandardCharsets.UTF_8));OutputStream out=s.getOutputStream();String first=in.readLine();if(first==null)return;String[] parts=first.split(" ");String rawPath=parts.length>1?parts[1]:"/";String path=rawPath;int queryMark=path.indexOf('?');if(queryMark>=0)path=path.substring(0,queryMark);int length=0;String line;while((line=in.readLine())!=null&&!line.isEmpty()){if(line.toLowerCase().startsWith("content-length:"))length=Math.min(2048,Integer.parseInt(line.substring(15).trim()));}
  if("GET".equals(parts[0])&&"/dashboard".equals(path)){if(!isPrivateClient(s.getInetAddress())){reply(out,403,"text/plain","LAN only".getBytes(StandardCharsets.UTF_8));return;}String dest="http://"+s.getLocalAddress().getHostAddress()+":8765/?token="+URLEncoder.encode(BridgeService.token(context),"UTF-8");byte[] h=("HTTP/1.1 302 Found\r\nLocation: "+dest+"\r\nCache-Control: no-store\r\nContent-Length: 0\r\nConnection: close\r\n\r\n").getBytes(StandardCharsets.UTF_8);out.write(h);out.flush();return;}
  if("GET".equals(parts[0])&&"/apps".equals(path)){reply(out,200,"application/json; charset=utf-8",AppShortcuts.touchpadJson(context).getBytes(StandardCharsets.UTF_8));return;}
  if("GET".equals(parts[0])&&"/mirror/status".equals(path)){String json="{\"active\":"+MirrorCapture.active()+",\"hasFrame\":"+(MirrorCapture.frame()!=null)+",\"width\":"+MirrorCapture.width()+",\"height\":"+MirrorCapture.height()+"}";reply(out,200,"application/json",json.getBytes(StandardCharsets.UTF_8));return;}
  if("GET".equals(parts[0])&&"/mirror/frame".equals(path)){byte[] frame=MirrorCapture.frame();if(frame==null){reply(out,503,"text/plain","鏡像未啟動，請先在 AI Box 授權".getBytes(StandardCharsets.UTF_8));}else reply(out,200,"image/jpeg",frame);return;}
  if("GET".equals(parts[0])&&"/media/status".equals(path)){try{String d=vehicleRequest("/api",false);reply(out,200,"application/json",d.getBytes(StandardCharsets.UTF_8));}catch(Exception e){reply(out,503,"text/plain","unavailable".getBytes(StandardCharsets.UTF_8));}return;}
  if("POST".equals(parts[0])&&rawPath.startsWith("/media/control?cmd=")){String cmd=rawPath.substring(rawPath.indexOf('=')+1);if(!cmd.matches("prev|play|next")){reply(out,400,"text/plain","invalid".getBytes(StandardCharsets.UTF_8));return;}try{String d=vehicleRequest("/control?cmd="+cmd+"&scope=auto",true);reply(out,200,"application/json",d.getBytes(StandardCharsets.UTF_8));}catch(Exception e){reply(out,503,"text/plain",String.valueOf(e.getMessage()).getBytes(StandardCharsets.UTF_8));}return;}
  if("GET".equals(parts[0])&&"/volume".equals(path)){try{String data=vehicleRequest("/api",false);org.json.JSONObject root=new org.json.JSONObject(data);org.json.JSONObject v=root.optJSONObject("values");Object raw=v==null?null:v.opt("Sound_Volume");int current=-1;String source="missing";
   if(raw instanceof org.json.JSONArray){org.json.JSONArray entries=(org.json.JSONArray)raw;for(int i=0;i<entries.length();i++){org.json.JSONObject entry=entries.optJSONObject(i);if(entry!=null&&"Volume".equalsIgnoreCase(entry.optString("key"))){try{current=(int)Math.round(Double.parseDouble(String.valueOf(entry.opt("value"))));source="exlap-list";}catch(Exception ignored){}break;}}}
   else if(raw instanceof org.json.JSONObject){org.json.JSONObject obj=(org.json.JSONObject)raw;current=obj.optInt("Volume",-1);source="object";}
   org.json.JSONObject result=new org.json.JSONObject();result.put("volume",current);result.put("available",current>=0);result.put("source",source);result.put("mediaExlapEnabled",root.optBoolean("mediaExlapEnabled",false));result.put("mediaSessionReady",root.optBoolean("mediaSessionReady",false));reply(out,200,"application/json",result.toString().getBytes(StandardCharsets.UTF_8));}catch(Exception e){reply(out,503,"text/plain",("車機音量讀取失敗: "+e.getMessage()).getBytes(StandardCharsets.UTF_8));}return;}
  if("GET".equals(parts[0])&&"/".equals(path)){byte[] html=readAsset();reply(out,200,"text/html; charset=utf-8",html);return;}
  if("POST".equals(parts[0])&&"/action".equals(path)&&length>0){char[] buf=new char[length];int n=0;while(n<length){int k=in.read(buf,n,length-n);if(k<0)break;n+=k;}String body=new String(buf,0,n);String[] p=body.split("&");String auth="",type="";float dx=0,dy=0,sx=-1,sy=-1;long duration=0;for(String entry:p){String[] kv=entry.split("=",2);if(kv.length<2)continue;String val=URLDecoder.decode(kv[1],"UTF-8");switch(kv[0]){case "token":auth=val;break;case "type":type=val;break;case "dx":dx=Float.parseFloat(val);break;case "dy":dy=Float.parseFloat(val);break;case "duration":duration=Long.parseLong(val);break;case "sx":sx=Float.parseFloat(val);break;case "sy":sy=Float.parseFloat(val);break;}}
   if(!isPrivateClient(s.getInetAddress())){reply(out,403,"text/plain","僅允許區域網路".getBytes(StandardCharsets.UTF_8));return;}
   if("vol_up".equals(type)||"vol_down".equals(type)){try{String result=vehicleRequest("/control?cmd="+("vol_up".equals(type)?"up":"down")+"&scope=vehicle",true);boolean ok=new org.json.JSONObject(result).optBoolean("ok");reply(out,ok?200:503,"application/json",result.getBytes(StandardCharsets.UTF_8));}catch(Exception e){reply(out,503,"text/plain",String.valueOf(e.getMessage()).getBytes(StandardCharsets.UTF_8));}return;}
   if(type.startsWith("pkg:")){String pkg=type.substring(4);if(!AppShortcuts.touchpadJson(context).contains("\""+pkg+"\"")){reply(out,403,"text/plain","未設定此快捷 App".getBytes(StandardCharsets.UTF_8));return;}}
   TouchService a=TouchService.active;boolean ok=a!=null&&("status".equals(type)||("swipe_at".equals(type)?a.swipeAt(sx,sy,dx,dy,duration):a.action(type,dx,dy)));reply(out,ok?200:503,"text/plain",(ok?"OK":"無障礙服務未啟用或操作失敗").getBytes());return;
  }
  reply(out,404,"text/plain","Not found".getBytes());
 }catch(Exception ignored){}}
 private String vehicleRequest(String path,boolean post)throws IOException {String sep=path.contains("?")?"&":"?";URL u=new URL("http://127.0.0.1:8765"+path+sep+"token="+URLEncoder.encode(BridgeService.token(context),"UTF-8"));HttpURLConnection c=(HttpURLConnection)u.openConnection();c.setConnectTimeout(1500);c.setReadTimeout(2500);if(post)c.setRequestMethod("POST");try(InputStream in=c.getInputStream();ByteArrayOutputStream b=new ByteArrayOutputStream()){byte[] bytes=new byte[2048];int n;while((n=in.read(bytes))!=-1)b.write(bytes,0,n);return b.toString("UTF-8");}finally{c.disconnect();}}
 private boolean isPrivateClient(InetAddress ip){if(ip.isLoopbackAddress()||ip.isSiteLocalAddress())return true;return false;}
 private byte[] readAsset()throws IOException{try(InputStream in=context.getAssets().open("touchpad.html");ByteArrayOutputStream b=new ByteArrayOutputStream()){byte[] x=new byte[4096];int n;while((n=in.read(x))!=-1)b.write(x,0,n);return b.toByteArray();}}
 private void reply(OutputStream out,int code,String type,byte[] data)throws IOException{String header="HTTP/1.1 "+code+" OK\r\nContent-Type: "+type+"\r\nContent-Length: "+data.length+"\r\nCache-Control: no-store\r\nConnection: close\r\n\r\n";out.write(header.getBytes(StandardCharsets.UTF_8));out.write(data);out.flush();}

}
